AND cai.point_id IN
#{pointId}

SELECT cai.id, cai.analysis_id, cai.sentence_id, cai.original_sentence, cai.problem_types, cai.point_id, cai.error_point, cai.suggestion, cai.created_at FROM conversation_analysis_item cai INNER JOIN conversation_analysis ca ON cai.analysis_id = ca.analysis_id WHERE ca.user_id = #{userId} AND ca.status = 'success' AND cai.point_id IS NOT NULL
AND cai.point_id IN
#{pointId}
AND cai.created_at >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
ORDER BY cai.created_at DESC, cai.id DESC LIMIT #{limit}

